typedef float rational_t;

class vector3d
{
public:
  rational_t x, y, z;

  vector3d() {}
  vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  vector3d(rational_t _x, rational_t _y, rational_t _z)
  {
    x = _x;
    y = _y;
    z = _z;
  }
};

inline vector3d cross(const vector3d& a, const vector3d& b)
{
  vector3d v( a.y * b.z - a.z * b.y,
              a.z * b.x - a.x * b.z,
              a.x * b.y - a.y * b.x );
  return v;
}

class vm_stack
{
public:
  char* SP;

  char* get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
};

void error(const char*);

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()

#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( "script stack overflow" )

#define SLF_DONE \
  return true

class slf_cross3_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vector3d v1;
    vector3d v2;
  };

  virtual bool operator()(vm_stack& stack,entry_t entry);
};

bool slf_cross3_t::operator()(vm_stack& stack,entry_t entry)
{
  SLF_PARMS;
  vector3d result = cross(parms->v1,parms->v2);
  SLF_RETURN;
  SLF_DONE;
}
